import { MeshStandardNodeMaterial, MeshBasicNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import {
  texture,
  uv,
  mul,
  float,
  vec3,
  vec4,
  mix,
  add,
  sub,
  pow,
  saturate,
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const {
    Group,
    Mesh,
    PlaneGeometry,
    AmbientLight,
    DirectionalLight,
    Color,
  } = ctx.THREE;

  const root = new Group();

  // ---------- Solid Background ----------
  const BG_W = 8;
  const BG_H = 6;
  const bgGeom = new PlaneGeometry(BG_W, BG_H);
  const bgMat = new MeshBasicNodeMaterial({ color: new Color('#0b0b10') });
  const bgPlane = new Mesh(bgGeom, bgMat);
  bgPlane.position.set(0, 0, -3);
  root.add(bgPlane);

  // ---------- Bottom Scrim Gradient ----------
  const gradGeom = new PlaneGeometry(BG_W, BG_H);
  const gradMat = new MeshBasicNodeMaterial();
  gradMat.transparent = true;
  const uvNode = uv();
  const vPos = uvNode.y; // vertical
  const gradStart = vec4(0x0b / 255, 0x0b / 255, 0x10 / 255, 0.0); // #0b0b1000
  const gradEnd = vec4(0x0b / 255, 0x0b / 255, 0x10 / 255, 0.92); // #0b0b10eb
  gradMat.colorNode = mix(gradStart, gradEnd, vPos);
  const gradPlane = new Mesh(gradGeom, gradMat);
  gradPlane.position.set(0, -1.5, -2.4);
  root.add(gradPlane);

  // ---------- Lighting ----------
  const ambient = new AmbientLight(0xffffff, 0.6);
  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(1, 1, 2).normalize();
  const rimLight = new DirectionalLight(0xffffff, 0.8);
  rimLight.position.set(-1, -0.5, 2).normalize();
  const fillLight = new DirectionalLight(0xffffff, 0.4);
  fillLight.position.set(-0.5, 0.2, 1).normalize();
  root.add(ambient, keyLight, rimLight, fillLight);

  // ---------- Photo Plane ----------
  const PLANE_W = 4.0;
  const PLANE_H = 2.5;
  const planeGeom = new PlaneGeometry(PLANE_W, PLANE_H, 64, 64);
  const planeMat = new MeshStandardNodeMaterial();
  planeMat.transparent = true;
  planeMat.opacity = 0;
  planeMat.roughness = 0.6;
  planeMat.metalness = 0.0;
  const photoPlane = new Mesh(planeGeom, planeMat);
  root.add(photoPlane);

  // ---------- Load Textures ----------
  let imageTex, depthTex;
  ctx.textureLoader.loadTexture(config.imageUrl).then((t) => {
    imageTex = t;
    applyMaterial();
  });
  ctx.textureLoader.loadTexture(config.depthMapUrl).then((t) => {
    depthTex = t;
    applyMaterial();
  });

  function applyMaterial() {
    if (!imageTex || !depthTex) return;

    const colorNode = texture(imageTex);
    const dispTex = texture(depthTex);
    const displacementNode = mul(dispTex.r, float(0.18));

    // ---- Filmic Grade ----
    // Lift blacks to #0d0d12
    const lifted = add(colorNode, vec3(0x0d / 255, 0x0d / 255, 0x12 / 255));
    // Desaturate 8% preserving red
    const desat = mix(lifted, vec3(lifted.r, lifted.g, lifted.b).multiplyScalar(0.92), float(0.08));
    // Increase contrast 12%
    const mid = float(0.5);
    const contrasted = mix(
      add(mul(sub(desat, mid), float(1.12)), mid, float(0.5)
    );
    // Shoulder highlights toward paper color #e8ecf2 (12% blend)
    const graded = mix(contrasted, vec3(0xe8 / 255, 0xec / 255, 0xf2 / 255), float(0.12));

    planeMat.colorNode = graded;
    planeMat.displacementNode = displacementNode;
    planeMat.needsUpdate = true;
  }

  // ---------- Caption Block ----------
  const captionGroup = new Group();
  const PAD = 0.5; // 2 × base unit (0.25)
  const startX = -PLANE_W / 2 + PAD;
  const startY = -PLANE_H / 2 + PAD;
  // Initial offset for rise animation
  captionGroup.position.set(startX, startY + 0.4, 0.01);
  root.add(captionGroup);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const lineSpacing = 0.25;

  const colors = config.visualSpec?.colors ?? {};
  const inkColor = colors.ink ?? '#16161d';
  const paperColor = colors.paper ?? '#e8ecf2';
  const accentColor = colors.accent ?? '#ff2a38';

  let cursorY = 0;
  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    const role = item.role ?? '';
    const fontSize = item.typography?.fontSize ?? 13;
    const txt = ctx.fontAtlas.createText(item.text ?? item.content ?? '', {
      fontSize,
      color: role === 'kicker' ? inkColor : paperColor,
      align: 'left',
    });
    txt.position.set(0, -cursorY, 0);
    captionGroup.add(txt);
    cursorY += lineSpacing;

    // Insert accent bar after headline (if this item is headline)
    if (role === 'headline') {
      const barGeom = new PlaneGeometry(0.75, 0.02);
      const barMat = new MeshStandardNodeMaterial({
        color: accentColor,
        emissive: accentColor,
        emissiveIntensity: 1.8,
        roughness: 0.5,
        metalness: 0,
        transparent: false,
      });
      const bar = new Mesh(barGeom, barMat);
      bar.position.set(0, -cursorY + 0.1, 0);
      captionGroup.add(bar);
    }
  }

  // ---------- Cinematic Primitives ----------
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const handle = fn(photoPlane, prim.params);
        primitiveHandles.push(handle);
      }
    }
  }

  // ---------- Animations ----------
  const tl = gsap.timeline();
  tl.to(
    planeMat,
    {
      opacity: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      onUpdate: () => {
        planeMat.needsUpdate = true;
      },
    },
  );
  tl.to(
    captionGroup.position,
    {
      y: startY,
      duration: 0.7,
      ease: 'cubic-bezier(0.215,0.61,0.355,1)',
      delay: 0.12,
    },
    '<',
  );

  // ---------- Cleanup ----------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    tl.kill();
    primitiveHandles.forEach((h) => {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    });
    // Dispose geometries & materials
    planeGeom.dispose();
    planeMat.dispose();
    bgGeom.dispose();
    bgMat.dispose();
    gradGeom.dispose();
    gradMat.dispose();
    if (imageTex) imageTex.dispose();
    if (depthTex) depthTex.dispose();
    // Dispose caption meshes
    captionGroup.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry && obj.geometry.dispose();
        obj.material && obj.material.dispose();
      }
    });
    // Dispose lights
    ambient.dispose();
    keyLight.dispose();
    rimLight.dispose();
    fillLight.dispose();
  };

  return root;
}
